def entityParser(text):
    entities = {
        '&quot;': '"', '&apos;': "'", '&amp;': '&',
        '&gt;': '>', '&lt;': '<', '&frasl;': '/',
    }
    i = 0
    n = len(text)
    result = []
    while i < n:
        if text[i] == '&':
            found = False
            for ent, char in entities.items():
                if text.startswith(ent, i):
                    result.append(char)
                    i += len(ent)
                    found = True
                    break
            if not found:
                result.append('&')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)
